extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_scene("res://basket.tscn")
	if not check("basket_loaded", basket != null, "La scena basket.tscn deve caricarsi correttamente"):
		return
	check("const_pos", basket.get("START_POSITION") == Vector2(576, 600), "La costante START_POSITION deve valere Vector2(576, 600)")
	var name_val = get_prop(basket, "player_name")
	check("var_name", name_val == "Cesto" and typeof(name_val) == TYPE_STRING, "La variabile player_name deve essere String con valore 'Cesto'")
	var speed_val = get_prop(basket, "speed")
	check("var_speed", speed_val == 350.0 and typeof(speed_val) == TYPE_FLOAT, "La variabile speed deve essere float con valore 350.0")
	var lives_val = get_prop(basket, "lives")
	check("var_lives", lives_val == 3 and typeof(lives_val) == TYPE_INT, "La variabile lives deve essere int con valore 3")
	var active_val = get_prop(basket, "is_active")
	check("var_active", active_val == true and typeof(active_val) == TYPE_BOOL, "La variabile is_active deve essere bool con valore true")
	var label := find_by_name(basket, "Label") as Label
	if not check("label_exists", label != null, "Il nodo Label deve trovarsi all'interno di Basket"):
		return
	var expected_text := "Cesto | Vite: 3 | Vel: " + str(speed_val)
	check("label_text", label.text == expected_text, "Il testo del Label deve mostrare nome, vite e velocità formattati correttamente")
	check("basket_pos", basket.position == Vector2(576, 600), "La posizione del cesto deve corrispondere a START_POSITION")
